//https://leetcode.com/problems/image-smoother/
class Solution {
public:
    vector<vector<int>> imageSmoother(vector<vector<int>>& img) {
        int row = img.size();
        int col = img[0].size();
        vector<vector<int>> res = img;
        int dx[] = {-1, 1, 0, 0, 1, -1, -1, 1};
        int dy[] = {0, 0, 1, -1, 1, -1, 1, -1};
        for(int r=0; r<row; r++){
            for(int c=0; c<col; c++){
                int count = 1;
                int sum = img[r][c];
                for(int i=0; i<8; i++){
                    int x = dx[i] + r;
                    int y = dy[i] + c;

                    if(x >= 0 && x < row && y >= 0 && y < col){
                        count++;
                        sum += img[x][y];
                    }
                }
                res[r][c] = floor(sum/count);
            }
        }
        return res;
    }
};

